void Solver::rephase() {
    // 1. Reset the rephase counter.
    rephases = 0;

    // 2. Dynamically tighten the threshold.
    //    When many conflicts have been seen we want to update local_best more often.
    if (conflicts > 20000) {
        threshold = (int)(threshold * 0.80);   // aggressive tightening
    } else if (conflicts > 10000) {
        threshold = (int)(threshold * 0.85);
    } else {
        threshold = (int)(threshold * 0.95);   // gentle tightening
    }
    if (threshold < 1) threshold = 1;           // safety guard

    // 3. Grow the rephase limit gradually so that rephasing does not happen too frequently.
    //    The increment is larger when we have already performed many rephases.
    rephase_limit = (int)(rephase_limit * 1.15) + 4096;
    if (rephase_limit < 8192) rephase_limit = 8192; // minimum bound

    // 4. Adjust saved phases based on recent LBD behaviour.
    //    If the recent LBD average is worsening, invert a random half of the phases;
    //    otherwise, fall back to the best local phase seen so far.
    if (lbd_queue_size == 50 && fast_lbd_sum > slow_lbd_sum) {
        // Invert phases for a random subset (≈50%) to diversify search.
        for (int i = 1; i <= vars; ++i) {
            if (rand() % 2) saved[i] = -saved[i];
        }
    } else {
        // Keep the locally best polarity.
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    }

    // 5. Reset the VSIDS activity increment to avoid excessive decay.
    var_inc = 1.0;
}
